"""Actual rootless OpenSSH setup for the already-authorized installation, not an approval gate."""
import base64
from pathlib import Path
import subprocess

from . import artifacts as a

# Use the stock procursus OpenSSH daemon (port 22, all interfaces, host keys auto-
# generated by sshd-keygen-wrapper). No hand-rolled loopback service.
LABEL = 'com.openssh.sshd'
NATIVE_PLIST = '/var/jb/Library/LaunchDaemons/com.openssh.sshd.plist'
SETUP = '''#!/var/jb/bin/sh
PATH=/var/jb/usr/bin:/var/jb/bin:/var/jb/usr/sbin:/var/jb/sbin:/usr/bin:/bin:/usr/sbin:/sbin
export PATH
mkdir -p /var/jb/var/empty
chmod 0755 /var/jb/var/empty
# OpenSSH 9.7 always uses privilege separation with the compiled-in user "sshd";
# the bootstrap only ships "_sshd", so sshd aborts each connection after KEX until
# a real "sshd" user exists. Create it once (uid 574, group of _sshd).
if ! /var/jb/usr/bin/grep -q '^sshd:' /var/jb/etc/master.passwd; then
    printf 'sshd:*:574:75::0:0:sshd Privilege separation:/var/jb/var/empty:/var/jb/usr/bin/false\\n' >> /var/jb/etc/master.passwd
    /var/jb/usr/sbin/pwd_mkdb -p /var/jb/etc/master.passwd
fi
# Install the dedicated client public key for root key-based login.
mkdir -p /var/jb/var/root/.ssh
cat /var/jb/etc/ssh/n56-authorized_keys/root > /var/jb/var/root/.ssh/authorized_keys
chmod 700 /var/jb/var/root /var/jb/var/root/.ssh
chmod 600 /var/jb/var/root/.ssh/authorized_keys
# Upstream root is locked; give it the usual jailbreak password so Wi-Fi password login works.
if [ ! -f /var/jb/.n56/ssh-account-configured ]; then
    # pw(8) rejects the bootstrap's own `nobody` entry (uid -2), so set the classic
    # iOS DES hash of "alpine" directly.
    /var/jb/usr/bin/sed -i 's|^root:[^:]*:|root:/smx7MYTQIi2M:|' /var/jb/etc/master.passwd
    /var/jb/usr/sbin/pwd_mkdb -p /var/jb/etc/master.passwd
    : > /var/jb/.n56/ssh-account-configured
fi
# Load the stock OpenSSH daemon (com.openssh.sshd): port 22 on all interfaces.
if ! /var/jb/usr/libexec/n56-binpack/bin/launchctl print system/com.openssh.sshd >/dev/null 2>&1; then
    /var/jb/usr/libexec/n56-binpack/bin/launchctl bootstrap system ''' + NATIVE_PLIST + '''
fi
'''


def material(out, public_key=None):
    if public_key is None:
        directory = out / 'ssh/client'; directory.mkdir(parents=True, exist_ok=True)
        private = directory / 'id_ed25519'
        if not private.exists():
            subprocess.run(['ssh-keygen', '-q', '-t', 'ed25519', '-N', '', '-C', 'n56-ios15-rootless-client',
                            '-f', str(private)], check=True, capture_output=True)
        private.chmod(0o600)
        public_key = private.with_name(private.name + '.pub')
        source = 'dedicated generated local key; private key stays outside payload/TC'
    else:
        public_key = Path(public_key)
        private = None
        source = 'caller-provided public key'
    text = public_key.read_text().strip()
    pieces = text.split()
    if len(pieces) < 2 or pieces[0] not in ('ssh-ed25519', 'ssh-rsa', 'ecdsa-sha2-nistp256') or '\n' in text:
        raise ValueError('SSH authorized key must be one ordinary public key, not a private key/options script')
    base64.b64decode(pieces[1], validate=True)
    # The stock com.openssh.sshd daemon (shipped in the bootstrap) is what listens;
    # we only stage the client public key and the setup script that loads it.
    files = {
        'etc/ssh/n56-authorized_keys/root': ((text + '\n').encode(), 0o600),
        '.n56/setup-ssh.sh': (SETUP.encode(), 0o755),
    }
    report = dict(schema=1, configured=True, started_on_device=False, listen_address='0.0.0.0', port=22,
                  authentication='publickey+password', user='root', public_key_source=source,
                  public_key_sha256=a.sha(public_key), private_client_key=str(private) if private else None,
                  host_keys_generated_on_firstboot=True, root_password='alpine',
                  launchd_label=LABEL, package_files=list(files), separate_firstboot_approval=False)
    a.write_json(out / 'ssh-plan.json', report)
    return files, report
